// Registration and reporting share the same cumulative percentage model.
const baseRender=render, baseDetail=detail;
const monthNow=()=>PlanModel.monthNow();
const monthList=(start,end)=>PlanModel.months(start,end);
const progress=x=>PlanModel.summary(x);
const copyObject=x=>JSON.parse(JSON.stringify(x||{}));
function persistRecords(next){try{localStorage.setItem(key,JSON.stringify(next));data=next;return true}catch{toast('저장 공간을 확인해 주세요. 입력한 내용은 화면에 유지되어 있습니다.',true);return false}}
function toast(message,error=false){let el=document.querySelector('#toast');if(!el){el=document.createElement('div');el.id='toast';el.setAttribute('role','status');document.body.append(el)}el.textContent=message;el.className=error?'toast error':'toast';el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500)}
function refreshProgress(){document.querySelectorAll('tr[data-id]').forEach(tr=>{const x=data.find(a=>a.id===tr.dataset.id);if(!x)return;const p=progress(x);tr.cells[5].innerHTML=`<span class="progress-label ${p.late?'late':p.missing?'pending':''}">${esc(p.label)}</span><span class="muted">${esc(p.note)}</span>`});const pending=data.filter(x=>!x.archivedAt&&!['보류','완료'].includes(x.status)&&progress(x).missing).length,late=data.filter(x=>!x.archivedAt&&!['보류','완료'].includes(x.status)&&progress(x).late).length;const el=document.querySelector('#monthly-summary');if(el)el.textContent=`월별 실적 확인 필요 ${pending}건 · 누적 지연 ${late}건`}
render=function(){baseRender();refreshProgress()};
document.querySelector('.banner').insertAdjacentHTML('afterend','<div id="monthly-summary" class="monthly-summary"></div>');
document.querySelector('main').insertAdjacentHTML('afterend','<main class="main registration-page" id="registrationPage" hidden></main>');
let draftMonthly={},goalYear=Number(PlanModel.today().slice(0,4)),registrationId='',registrationReturn='list',goalErrors=[];
function legacyRecordsHTML(x){const legacy=x.legacyAggregateReports?{...x.legacyAggregateReports,unit:'전환 전 전체 누적 %'}:x.legacyPlan||(x.planMode!=='cumulative-percent-v1'&&Object.keys(x.monthly||{}).length?{monthly:x.monthly,unit:x.unit}:null);if(!legacy)return '';return `<details class="legacy-note"><summary>기존 단위의 입력 기록 확인 (${esc(legacy.unit||'단위 미지정')})</summary><div class="annual-scroll"><table class="legacy-table"><thead><tr><th>월</th><th>목표</th><th>실적</th><th>지연 사유</th><th>Catch Up Plan</th></tr></thead><tbody>${Object.entries(legacy.monthly||{}).sort(([a],[b])=>a.localeCompare(b)).map(([m,row])=>`<tr><td>${esc(m)}</td>${['goal','actual','reason','catchup'].map(k=>`<td>${esc(row[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`}
function registrationDates(){return {startDate:document.querySelector('#startDate')?.value||'',endDate:document.querySelector('#endDate')?.value||''}}
function readAnnualGoals(){document.querySelectorAll('#annualGrid [data-goal-month]:not(:disabled)').forEach(el=>{draftMonthly[el.dataset.goalMonth]??={};draftMonthly[el.dataset.goalMonth].goal=el.value})}
function openForm(id){closeModal();registrationReturn=document.querySelector('#dashboardPage')&&!document.querySelector('#dashboardPage').hidden?'dashboard':'list';registrationId=id||'';const x=data.find(a=>a.id===id)||{},isLegacy=x.planMode!=='cumulative-percent-v1'&&Object.keys(x.monthly||{}).length;draftMonthly=x.planMode==='cumulative-percent-v1'?{...copyObject(x.monthlyArchive),...copyObject(x.monthly)}:{};goalYear=Number(PlanModel.today().slice(0,4));goalErrors=[];window.StepUI?.init(x);
const f=(name,label,placeholder='',required=false)=>`<div class="field"><label for="reg-${name}">${label}${required?' <span class="required">*</span>':''}</label><input id="reg-${name}" name="${name}" value="${esc(x[name]||'')}" placeholder="${placeholder}" ${required?'required':''} maxlength="${name==='title'?150:300}"></div>`;
const area=(name,label,placeholder)=>`<div class="field"><label for="reg-${name}">${label}</label><textarea id="reg-${name}" name="${name}" placeholder="${placeholder}">${esc(x[name]||'')}</textarea></div>`;
const start=x.startDate||(x.startMonth?x.startMonth+'-01':''),end=x.endDate||(x.endMonth?x.endMonth+'-'+String(new Date(Number(x.endMonth.slice(0,4)),Number(x.endMonth.slice(5)),0).getDate()).padStart(2,'0'):'');
document.querySelector('#registrationPage').innerHTML=`<div class="registration-heading"><button class="text-button" type="button" onclick="leaveRegistration()">전체 과제 / 등록</button><div class="eyebrow">PROJECT ${id?'EDIT':'CREATE'}</div><h1>${id?'과제 수정':'새 과제 등록'}</h1><p>추진 일정을 정하고, 월말까지 달성할 누적 진척률을 계획하세요.</p></div><form id="form" class="registration-form" novalidate onsubmit="submitForm(event,'${esc(id||'')}')"><div id="registrationErrors" class="form-error-summary" role="alert" hidden></div><section class="form-section"><div class="form-section-heading"><h2>기본 정보</h2><span>* 필수 입력</span></div><div class="grid">${f('title','과제 제목','과제명을 입력하세요',true)}${f('team','소속 팀','담당 팀명을 입력하세요',true)}<div class="field"><label for="reg-type">과제 분류</label><select name="type" id="reg-type"><option value="">선택하세요</option>${['팀 과제','담당 과제'].map(a=>`<option ${x.type===a?'selected':''}>${a}</option>`).join('')}</select></div></div></section><section class="form-section schedule-section"><div class="form-section-heading"><div><h2>추진 일정 및 연간 목표</h2><p>목표는 과제 시작부터 해당 월말까지의 누적 진척률입니다.</p></div><span class="unit-badge">누적 진척률 %</span></div>${isLegacy?'<div class="legacy-note">기존 계획은 다른 단위로 입력되어 있습니다. 기존 기록을 보존한 채 누적 진척률 계획을 새로 입력해 주세요.</div>':''}${legacyRecordsHTML(x)}<div class="period-fields"><div class="field"><label for="startDate">과제 시작일 <span class="required">*</span></label><input type="date" id="startDate" name="startDate" value="${esc(start)}" required oninput="updatePeriod()"></div><span class="date-divider">~</span><div class="field"><label for="endDate">과제 종료일 <span class="required">*</span></label><input type="date" id="endDate" name="endDate" value="${esc(end)}" required oninput="updatePeriod()"></div><div id="periodSummary" class="period-summary"></div></div><div id="periodError" class="inline-error" role="status"></div><div class="annual-toolbar"><div class="annual-year"><label for="goalYear">연간 목표</label><select id="goalYear" aria-label="목표 연도" onchange="selectGoalYear(this.value)"></select></div><div class="schedule-legend"><span><i class="legend-active"></i>과제 기간</span><span><i class="legend-disabled"></i>기간 외</span></div><button type="button" class="secondary small" onclick="fillEvenGoals()">목표 균등 배분</button></div><div id="annualGrid"></div><div id="annualFeedback" class="annual-feedback" aria-live="polite"></div><div class="plan-guidance"><span>Step별 0~비중 범위 · 이전 월 이상 · 마지막 달은 해당 비중</span><span>연도가 바뀌어도 누적 진척률이 이어집니다. 좁은 화면에서는 표를 좌우로 이동하세요.</span></div><div id="allYearStatus" class="all-year-status"></div></section><section class="form-section"><div class="form-section-heading"><h2>담당자</h2><span>조직도 연동 전 · 직접 입력</span></div><div class="grid">${f('po','PO','이름 입력')}${f('pm','PM','이름 입력')}${f('members','공동 수행자','쉼표로 구분해 입력')}</div></section><section class="form-section"><h2>대상 Tech <span class="required">*</span></h2><p>여러 기술을 선택할 수 있습니다.</p>${['DRAM','NAND','HBM','전체'].map(g=>`<fieldset class="tech-group"><legend>${g==='전체'?'전체 기술':g}</legend><div class="option-pills">${techs.filter(t=>g==='전체'?t==='All Tech':t.startsWith(g)).map(t=>`<label class="option-pill"><input type="checkbox" name="tech" value="${t}" aria-label="${t}" ${(x.tech||[]).includes(t)?'checked':''}><span>${esc(t.replace(g+': ',''))}</span></label>`).join('')}</div></fieldset>`).join('')}</section><section class="form-section"><h2>과제 내용</h2>${area('background','배경 / 목표','이 과제가 필요한 이유와 달성할 목표를 작성하세요.')}${area('kpi','KPI','성과를 확인할 지표와 기준을 작성하세요.')}${area('plan','추진 계획','주요 단계와 실행 계획을 작성하세요.')}<div class="field"><label>추가 분류</label><div class="checks">${['mHTRS','HTRS','AI','DT'].map(a=>`<label><input type="checkbox" name="special" value="${a}" ${(x.special||[]).includes(a)?'checked':''}>${a}</label>`).join('')}</div></div><div class="grid">${f('htrsSub','mHTRS / HTRS 하위 분류','추후 결정')}${f('aiSub','AI / DT 하위 분류','추후 결정')}</div></section>${id&&window.ApprovalWorkflow?ApprovalWorkflow.requestFields(x):''}<div class="registration-actions"><span>실적은 등록 후 ‘월별 실적 입력’에서 관리합니다.</span><div><button type="button" class="secondary" onclick="leaveRegistration()">취소</button><button type="submit" class="primary">${id?'변경 승인 요청':'과제 등록'}</button></div></div></form>`;showPage('registration');updatePeriod();if(window.StepUI&&!StepUI.enabled()){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent='Step별 계획으로 전환';b.onclick=()=>{readAnnualGoals();StepUI.convert(draftMonthly);b.remove();renderGoalFeedback()};document.querySelector('#annualGrid').before(b)}document.querySelector('#reg-title').focus()}
function leaveRegistration(){showPage(registrationReturn);window.scrollTo(0,0)}
function updatePeriod(){readAnnualGoals();const dates=registrationDates(),months=PlanModel.periodMonths(dates.startDate,dates.endDate);const valid=months.length>0;const current=Number(PlanModel.today().slice(0,4));let years=[...new Set([current,...PlanModel.years(dates.startDate,dates.endDate)])].sort((a,b)=>a-b);if(!years.includes(goalYear))goalYear=current;document.querySelector('#goalYear').innerHTML=years.map(y=>`<option ${y===goalYear?'selected':''} value="${y}">${y}년</option>`).join('');if(valid){let last=months.at(-1);draftMonthly[last]??={};if(!PlanModel.hasValue(draftMonthly[last].goal))draftMonthly[last].goal='100'}const old=data.find(a=>a.id===registrationId);const archived=valid&&Object.entries(old?.monthly||{}).some(([m,row])=>!months.includes(m)&&PlanModel.hasValue(row.actual));document.querySelector('#periodSummary').textContent=valid?`${months.length}개월 · ${dates.startDate.slice(0,4)===dates.endDate.slice(0,4)?'단일 연도':'여러 연도에 걸친 과제'}${archived?' · 제외된 월의 실적은 보관됩니다.':''}`:'시작일과 종료일을 선택하세요';document.querySelector('#periodError').textContent=dates.startDate&&dates.endDate&&!valid?'종료일은 시작일과 같거나 이후여야 합니다.':'';renderAnnualGrid();renderGoalFeedback()}
function selectGoalYear(year){readAnnualGoals();goalYear=Number(year);renderAnnualGrid();renderGoalFeedback()}
function renderAnnualGrid(){if(window.StepUI?.enabled()){StepUI.update(registrationDates(),goalYear);return}const {startDate,endDate}=registrationDates(),active=PlanModel.periodMonths(startDate,endDate);const months=Array.from({length:12},(_,i)=>`${goalYear}-${String(i+1).padStart(2,'0')}`);document.querySelector('#annualGrid').innerHTML=`<div class="annual-scroll" role="region" aria-label="${goalYear}년 월별 누적 목표" tabindex="0"><table class="annual-table"><thead><tr><th scope="col">월</th>${months.map((m,i)=>`<th scope="col" class="${active.includes(m)?'active-month':'inactive-month'}">${i+1}월</th>`).join('')}</tr></thead><tbody><tr><th scope="row">누적 목표</th>${months.map(m=>{let enabled=active.includes(m),error=goalErrors.some(e=>e.month===m);return `<td class="${enabled?'active-cell':'inactive-cell'}"><div class="percent-input"><input type="number" inputmode="decimal" min="0" max="100" step="0.1" data-goal-month="${m}" value="${enabled?esc(draftMonthly[m]?.goal??''):''}" ${enabled?'':'disabled'} aria-label="${goalYear}년 ${Number(m.slice(5))}월 누적 목표 (%)" ${error?'aria-invalid="true"':''} placeholder="${enabled?'0':'—'}" oninput="goalInput()"><span>%</span></div><div class="month-state">${enabled?(m===active.at(-1)?'최종 목표':'진행'):'기간 외'}</div></td>`}).join('')}</tr></tbody></table></div>`}
function goalInput(){readAnnualGoals();renderGoalFeedback();if(goalErrors.length){const dates=registrationDates();goalErrors=goalErrors.filter(e=>e.field!=='goal').concat(PlanModel.validatePlan({...dates,monthly:draftMonthly}));const box=document.querySelector('#registrationErrors');box.hidden=!goalErrors.length;box.innerHTML='<strong>입력 내용을 확인해 주세요.</strong><ul>'+goalErrors.slice(0,15).map(e=>'<li>'+esc(e.message)+'</li>').join('')+'</ul>'}document.querySelectorAll('[data-goal-month]').forEach(el=>{if(goalErrors.some(e=>e.month===el.dataset.goalMonth))el.setAttribute('aria-invalid','true');else el.removeAttribute('aria-invalid')})}
function renderGoalFeedback(){if(window.StepUI?.enabled()){document.querySelector('#annualFeedback').textContent='Step 정의 완료 후 월별 계획을 입력하세요. 각 Step 비중이 목표의 최대값입니다.';document.querySelector('#allYearStatus').innerHTML='';return}const dates=registrationDates(),months=PlanModel.periodMonths(dates.startDate,dates.endDate),visible=months.filter(m=>m.startsWith(String(goalYear))),filled=months.filter(m=>PlanModel.hasValue(draftMonthly[m]?.goal));document.querySelector('#annualFeedback').textContent=!months.length?'일정을 선택하면 해당 월의 입력칸만 활성화됩니다.':!visible.length?`${goalYear}년은 과제 기간에 포함되지 않습니다. 목표 연도를 변경해 주세요.`:`${goalYear}년 활성 ${visible.length}개월 · 전체 목표 입력 ${filled.length} / ${months.length}개월`;const years=PlanModel.years(dates.startDate,dates.endDate);document.querySelector('#allYearStatus').innerHTML=years.map(y=>{const ms=months.filter(m=>m.startsWith(String(y))),n=ms.filter(m=>PlanModel.hasValue(draftMonthly[m]?.goal)).length;return `<button type="button" class="year-status ${y===goalYear?'selected':''}" onclick="jumpGoalYear(${y})">${y}년 <strong>${n}/${ms.length}</strong></button>`}).join('')}
function jumpGoalYear(y){document.querySelector('#goalYear').value=String(y);selectGoalYear(y)}
function fillEvenGoals(){if(window.StepUI?.fill())return;readAnnualGoals();const {startDate,endDate}=registrationDates(),months=PlanModel.periodMonths(startDate,endDate);if(!months.length){document.querySelector('#periodError').textContent='먼저 추진 일정을 선택해 주세요.';return}months.forEach((m,i)=>{draftMonthly[m]??={};draftMonthly[m].goal=String(Math.round((i+1)/months.length*1000)/10)});goalErrors=[];renderAnnualGrid();renderGoalFeedback()}
function showRegistrationErrors(errors){goalErrors=errors;const box=document.querySelector('#registrationErrors');box.hidden=!errors.length;box.innerHTML=`<strong>입력 내용을 확인해 주세요.</strong><ul>${errors.slice(0,15).map(e=>`<li>${e.month?`<button type="button" onclick="jumpGoalYear(${Number(e.month.slice(0,4))})">${esc(e.message)}</button>`:esc(e.message)}</li>`).join('')}</ul>`;document.querySelectorAll('#form [aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));for(let e of errors){if(e.field){let el=document.querySelector('#'+(e.field==='startDate'||e.field==='endDate'?e.field:'reg-'+e.field));el?.setAttribute('aria-invalid','true')}}if(errors.length){if(errors[0].month)jumpGoalYear(Number(errors[0].month.slice(0,4)));box.scrollIntoView({behavior:'smooth',block:'center'})}}
function submitForm(e,id){e.preventDefault();readAnnualGoals();const form=e.target,f=new FormData(form),dates=registrationDates(),months=PlanModel.periodMonths(dates.startDate,dates.endDate);const errors=[];if(window.StepUI&&!StepUI.ready())errors.push({message:'Step 정의를 완료하고 월별 계획 입력 단계로 이동해 주세요.'});for(let [field,label] of [['title','과제 제목'],['team','소속 팀']])if(!String(f.get(field)||'').trim())errors.push({field,message:`${label}을 입력해 주세요.`});if(!f.getAll('tech').length)errors.push({field:'tech',message:'대상 Tech를 하나 이상 선택해 주세요.'});errors.push(...PlanModel.validatePlan(window.StepUI?.candidate({...dates,monthly:draftMonthly})||{...dates,monthly:draftMonthly}));if(errors.length){showRegistrationErrors(errors);return}const old=data.find(a=>a.id===id)||{},fields=Object.fromEntries([...f.entries()].filter(([k])=>!['tech','special','startDate','endDate','changeRequester','changeReason'].includes(k)).map(([k,v])=>[k,String(v).trim()]));const archive=old.planMode==='cumulative-percent-v1'?copyObject(old.monthlyArchive):{};if(old.planMode==='cumulative-percent-v1')for(let [m,row] of Object.entries(old.monthly||{}))if(!months.includes(m))archive[m]=row;let record={...old,...fields,id:id||crypto.randomUUID(),status:old.status||'계획',...dates,startMonth:months[0],endMonth:months.at(-1),unit:'%',planMode:'cumulative-percent-v1',tech:f.getAll('tech'),special:f.getAll('special'),monthly:Object.fromEntries(months.map(m=>[m,copyObject(draftMonthly[m])])),monthlyArchive:archive};if(old.planMode!=='cumulative-percent-v1'&&Object.keys(old.monthly||{}).length)record.legacyPlan={monthly:copyObject(old.monthly),unit:old.unit||'',startMonth:old.startMonth,endMonth:old.endMonth,monthlyArchive:copyObject(old.monthlyArchive)};record=window.StepUI?.candidate(record)||record;if(id&&window.ApprovalWorkflow)return ApprovalWorkflow.requestFromForm(record,old);const next=id?data.map(x=>x.id===id?record:x):[record,...data];if(!persistRecords(next))return;render();leaveRegistration();toast(id?'과제와 목표 계획을 저장했습니다.':'새 과제를 등록했습니다.')}
function annualReadOnly(x,year){const active=monthList(x.startMonth,x.endMonth),months=Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`);return `<div class="annual-scroll"><table class="annual-table"><thead><tr><th>월</th>${months.map((m,i)=>`<th class="${active.includes(m)?'active-month':'inactive-month'}">${i+1}월</th>`).join('')}</tr></thead><tbody>${[['goal','누적 목표'],['actual','누적 실적']].map(([k,label])=>`<tr><th>${label}</th>${months.map(m=>`<td class="${active.includes(m)?'active-cell':'inactive-cell'}">${active.includes(m)&&PlanModel.hasValue(x.monthly?.[m]?.[k])?esc(x.monthly[m][k])+'%':'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
detail=function(id){baseDetail(id);const x=data.find(a=>a.id===id),p=progress(x),section=document.createElement('section');section.className='monthly-section';const years=PlanModel.years(x.startDate,x.endDate);section.innerHTML=`<h3>추진 일정 및 누적 진척률</h3><p>${esc(x.startDate||'미정')} ~ ${esc(x.endDate||'미정')}</p><p class="detail-progress"><strong>${esc(p.label)}</strong> · ${esc(p.note)}</p>${x.planMode==='cumulative-percent-v1'?years.map(y=>`<h4>${y}년</h4>${annualReadOnly(x,y)}`).join(''):'<p class="legacy-note">누적 진척률 기준의 목표 계획을 등록해 주세요. 기존 기록은 유지됩니다.</p>'}${legacyRecordsHTML(x)}`;document.querySelector('#dialog .actions').before(section);if(PlanModel.isWeighted(x)){const host=document.createElement('div');section.append(host);StepUI.detail(host,x)}const edit=document.querySelector('#dialog .actions .primary');edit.textContent='과제 / 목표 수정';if(x.planMode==='cumulative-percent-v1'){const b=document.createElement('button');b.className='secondary';b.textContent='월별 실적 입력';b.onclick=()=>openPerformance(id);edit.before(b)}};
render();
